Build OK","sessionId":"","error":""}</content></tool_result_a5RB>
好，干净状态。重新理清思路：

**保留**：容器高度 gsap 动画（`duration: 0.05, power2.out`）
**修改**：文字的出现方式——从"opacity 突变 + 逐行 translateY"改为"整张纸从盒子上沿滑下"

问题是：容器高度增长时，文字在正常位置会被 `overflow:hidden` 逐行暴露（百叶窗）。

解法：容器展开过程中，文字行 `translateY = -fullHeight`（一直在容器上方），容器高度动画结束后，`slideInRows` 再把纸从上方滑下来。

但容器高度从 0 到 fullHeight 增长时，`-fullHeight` 的偏移量应该保持不变（因为 fullHeight 是最终高度，不是当前高度）。所以文字一直在 `y - fullHeight` 的位置，即容器上方，被裁切不可见。
<tool_rXDN name="package_proxy">
  <param name="params">{&quot;content&quot;: &quot;const fs = require(&apos;fs&apos;);
let code = fs.readFileSync(&apos;/root/kfmv4/src/client/modules/tree-render.ts&apos;, &apos;utf8&apos;);

// ====== 修改1：容器展开时，文字移到上方（不改容器动画） ======
const old1 = &apos;      // 展开前隐藏直接子行，避免在展开过程中暴露\n      container.children.forEach(c =&gt; { c.opacity = 0; });&apos;;
const new1 = &apos;      // 文字行移到容器上方，被 overflow:hidden 裁切；子容器隐藏\n      container.children.forEach(c =&gt; {\n        if (c.id?.startsWith(\&apos;expanded-\&apos;)) c.opacity = 0;\n        else if (c.id?.startsWith(\&apos;title-\&apos;) || c.id?.startsWith(\&apos;file-\&apos;)) c.transform.translateY = -fullHeight;\n      });&apos;;
if (code.includes(old1)) { code = code.replace(old1, new1); console.log(&apos;Done 1&apos;); }
else { console.log(&apos;Pattern 1 not found&apos;); }

// ====== 修改2：slideInRows - 不设 opacity，不重设 translateY ======
const old2 = &apos;  container.children.forEach(c =&gt; { c.opacity = 1; });\n  rows.forEach(r =&gt; { r.transform.translateY = -totalH; });\n  renderer?.setRoot(renderer!.getRoot()!);&apos;;
const new2 = &apos;  // 恢复子容器可见；文字行已在容器上方，等待滑入\n  container.children.forEach(c =&gt; {\n    if (c.id?.startsWith(\&apos;expanded-\&apos;)) c.opacity = 1;\n  });\n  renderer?.setRoot(renderer!.getRoot()!);&apos;;
if (code.includes(old2)) { code = code.replace(old2, new2); console.log(&apos;Done 2&apos;); }
else { console.log(&apos;Pattern 2 not found&apos;); }

// ====== 修改3：子容器展开时只隐藏孙容器 ======
const old3 = &apos;    child.children.forEach(c =&gt; { c.opacity = 0; });&apos;;
const new3 = &apos;    child.children.forEach(c =&gt; {\n      if (c.id?.startsWith(\&apos;expanded-\&apos;)) c.opacity = 0;\n    });&apos;;
if (code.includes(old3)) { code = code.replace(old3, new3); console.log(&apos;Done 3&apos;); }
else { console.log(&apos;Pattern 3 not found&apos;); }

// ====== 修改4：文字链 - 整张纸一起滑下 ======
const old4 = &apos;  // ====== 文字链：逐行滑入（不阻塞盒子链） ======\n  rows.forEach((row, i) =&gt; {\n    const rowDelay = (i * 25) / 1000;\n    gsap.to(row.transform, {\n      translateY: 0,\n      duration: 0.2,\n      ease: \&apos;power2.out\&apos;,\n      delay: rowDelay,\n      onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },\n    });\n  });&apos;;
const new4 = &apos;  // ====== 文字链：整张纸从盒子上沿一起滑下 ======\n  rows.forEach(r =&gt; {\n    gsap.to(r.transform, {\n      translateY: 0,\n      duration: 0.2,\n      ease: \&apos;power2.out\&apos;,\n      onUpdate: () =&gt; { renderer?.setRoot(renderer!.getRoot()!); },\n    });\n  });&apos;;
if (code.includes(old4)) { code = code.replace(old4, new4); console.log(&apos;Done 4&apos;); }
else { console.log(&apos;Pattern 4 not found&apos;); }

fs.writeFileSync(&apos;/root/kfmv4/src/client/modules/tree-render.ts&apos;, code);
&quot;, &quot;path&quot;: &quot;/tmp/fix_paper4.js&quot;}</param>
